insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_147'
from (values
('127.890.d.1.A',3,'A student lists airline, repair-station and general-aviation shop jobs, plus the idea of opening her own avionics shop. She is:','["identifying employment opportunities, including entrepreneurship", "describing seats", "describing tires", "ignoring careers"]'::jsonb,0,'Career options.','original'),
('127.890.d.1.A',4,'Starting your own maintenance shop is an example of:','["apprenticeship only", "entrepreneurship", "retirement", "unemployment"]'::jsonb,1,'Entrepreneur.','original'),
('127.890.d.1.B',3,'During a team inspection, a technician shares what she found and asks a coworker to double-check. She is:','["hiding findings", "ignoring the team", "contributing and collaborating as an effective team member", "working alone"]'::jsonb,2,'Teamwork.','original'),
('127.890.d.1.B',4,'A good team member in a hangar usually:','["skips handoffs", "blames others", "keeps secrets", "communicates findings and helps others"]'::jsonb,3,'Good teammate.','original'),
('127.890.d.1.C',3,'A mechanic reads the code of conduct and refuses to sign off work she did not perform. She is:','["identifying individual ethical and legal behavior standards according to the profession", "breaking rules", "guessing", "ignoring ethics"]'::jsonb,0,'Ethics standards.','original'),
('127.890.d.1.C',4,'Signing off work that you did not do or inspect is:','["good practice", "falsification and a violation of regulations", "efficient", "routine"]'::jsonb,1,'Falsification.','original'),
('127.890.d.1.D',3,'A student reads that aviation manuals and radio calls are in English worldwide, so language skill matters on the job. She is:','["describing tires", "ignoring language", "researching and discussing the impact of English language proficiency requirements", "describing seats"]'::jsonb,2,'English proficiency.','original'),
('127.890.d.1.D',4,'English proficiency matters in aviation because it:','["removes checklists", "lowers safety", "adds noise", "reduces misunderstandings in manuals and communication"]'::jsonb,3,'Why English.','original'),
('127.890.d.1.E',3,'A student studies how fatigue, stress and distraction affect a technician''s work. She is:','["identifying and explaining the technical knowledge and skills related to human factors", "ignoring people", "describing seats", "describing tires"]'::jsonb,0,'Human factors.','original'),
('127.890.d.1.E',4,'Human factors in maintenance study how people:','["build engines", "perform and make errors in their work environment", "weigh fuel", "paint planes"]'::jsonb,1,'Study of people.','original'),
('127.890.d.1.F',3,'A shop adds breaks, clear lighting and checklists so that fewer errors happen and people stay safe. They are:','["describing seats", "ignoring safety", "explaining the role of human factors in maintaining health and safety in the workplace", "describing tires"]'::jsonb,2,'Safety role.','original'),
('127.890.d.1.F',4,'Giving workers adequate rest helps safety because tired people:','["work faster", "never err", "notice more", "make more mistakes"]'::jsonb,3,'Fatigue.','original'),
('127.890.d.1.G',3,'A technician who admits a mistake right away helps the shop fix it before it flies. She shows how:','["employees'' personal responsibility attitudes can affect safety", "attitude is irrelevant", "blame is best", "hiding is better"]'::jsonb,0,'Responsibility.','original'),
('127.890.d.1.G',4,'An attitude of ''someone else will catch it'' can:','["lower risk", "lead to missed errors", "speed checks safely", "improve safety"]'::jsonb,1,'Complacency.','original'),
('127.890.d.1.H',3,'A coworker asks her to skip a required torque check to save time, and she weighs the safety risk and says no. She is:','["breaking a rule", "ignoring risk", "applying reasoning skills to make an ethical decision", "guessing"]'::jsonb,2,'Ethical choice.','original'),
('127.890.d.1.H',4,'When pressured to cut a corner on a safety item, the best response is to:','["skip the step", "agree quietly", "hide it", "follow the procedure and report the pressure"]'::jsonb,3,'Hold the line.','original'),
('127.890.d.1.I',3,'A shop requires closed-toe shoes, safety glasses and hair tied back near machines. They are:','["identifying industry standards related to employee appearance and health habits", "describing seats", "describing tires", "ignoring dress"]'::jsonb,0,'Appearance rules.','original'),
('127.890.d.1.I',4,'Hearing protection on the flight line follows from a standard that aims to prevent:','["more noise", "noise-induced hearing loss", "wet floors", "lost tools"]'::jsonb,1,'Hearing.','original'),
('127.890.d.1.J',3,'A technician writes a clear defect note and then explains the problem out loud to the next shift. She is:','["avoiding talk", "guessing", "practicing effective written and oral communication skills", "hiding notes"]'::jsonb,2,'Communication.','original'),
('127.890.d.1.J',4,'A good maintenance note is:','["hidden", "vague", "long and unclear", "specific, accurate and easy to read"]'::jsonb,3,'Clear notes.','original'),
('127.890.d.1.K',3,'A technician repeats the supervisor''s instructions back to confirm she heard them right. She is:','["practicing effective listening skills", "guessing", "interrupting", "ignoring"]'::jsonb,0,'Listening.','original'),
('127.890.d.1.K',4,'Repeating back an instruction helps because it:','["adds noise", "confirms that you understood", "hides errors", "wastes time"]'::jsonb,1,'Read-back.','original'),
('127.890.d.1.L',3,'A student learns that FAA words like ''shall'' and ''may'' carry different expectations in a regulation. She is:','["describing tires", "ignoring terms", "defining and applying FAA standard terms that have specific expectations for performance", "describing seats"]'::jsonb,2,'FAA terms.','original'),
('127.890.d.1.L',4,'In FAA language, ''shall'' means the action is:','["suggested", "forbidden", "optional", "mandatory"]'::jsonb,3,'Shall.','original'),
('127.890.d.2.A',3,'A student describes a workplace where people report problems without fear and managers act on them, and she maps who reports to whom. She is:','["describing safety culture and organizational structures in the work environment", "describing seats", "describing tires", "ignoring culture"]'::jsonb,0,'Safety culture.','original'),
('127.890.d.2.A',4,'A strong safety culture encourages workers to:','["hide mistakes", "report errors and hazards openly", "avoid reports", "skip training"]'::jsonb,1,'Open reporting.','original'),
('127.890.d.2.B',3,'A student separates slips, lapses and rule violations as types of mistakes people can make. She is:','["describing tires", "ignoring errors", "identifying and explaining types of human error and human factor principles", "describing seats"]'::jsonb,2,'Human error.','original'),
('127.890.d.2.B',4,'A slip is an error where a person:','["skips a rule on purpose", "plans the wrong action", "never acts", "intends the right action but does it wrong"]'::jsonb,3,'Slip.','original'),
('127.890.d.2.C',3,'A student shows how a skipped inspection, a rushed shift and a missing tool lined up before a missed bolt. She is:','["identifying and discussing the chain-of-events theory, including preconditions and contributing factors", "ignoring causes", "describing seats", "describing tires"]'::jsonb,0,'Error chain.','original'),
('127.890.d.2.C',4,'The chain-of-events idea says accidents happen when:','["one big failure only", "several small failures line up", "nothing fails", "tools break only"]'::jsonb,1,'Chain.','original'),
('127.890.d.2.D',3,'A student reviews the ''dirty dozen'' list, including lack of communication, complacency and fatigue, as causes of mistakes. She is:','["describing seats", "ignoring causes", "identifying and discussing the 12 common causes of mistakes in the aviation workplace", "describing tires"]'::jsonb,2,'Dirty dozen.','original'),
('127.890.d.2.D',4,'Which of these is one of the dirty dozen?','["Extra rest", "Clear manuals", "Good lighting", "Lack of assertiveness"]'::jsonb,3,'Dirty dozen item.','original'),
('127.890.d.2.E',3,'A student learns that a safety management system finds hazards, measures risk and tracks fixes in a company. She is:','["researching and discussing the purpose of safety management systems in the aviation workplace", "avoiding safety", "describing seats", "describing tires"]'::jsonb,0,'SMS.','original'),
('127.890.d.2.E',4,'A safety management system works by:','["hiding data", "identifying hazards and managing risk proactively", "skipping audits", "waiting for accidents"]'::jsonb,1,'Proactive.','original'),
('127.890.d.3.A',3,'A mechanic finds a cracked bracket and fills in the service difficulty report with the part number and details. She is:','["ignoring the crack", "hiding the form", "completing and submitting a malfunction and defect report", "painting the part"]'::jsonb,2,'Defect report.','original'),
('127.890.d.3.A',4,'Submitting a malfunction and defect report helps the FAA by:','["adding delays", "hiding problems", "lowering safety", "spotting trends in part failures"]'::jsonb,3,'Trends.','original'),
('127.890.d.3.B',3,'A student looks up maintenance-error cases from past accident reports and writes a summary of what went wrong. She is:','["researching and reporting on information regarding human factor errors", "describing tires", "describing seats", "ignoring cases"]'::jsonb,0,'Error research.','original'),
('127.890.d.3.B',4,'Studying past human-factor errors helps future technicians to:','["ignore risk", "avoid repeating the same mistakes", "repeat mistakes", "skip checks"]'::jsonb,1,'Learn from errors.','original'),
('127.890.d.4.A',3,'A student solves 3x + 6 = 21 to find the number of bolts needed and divides each side properly. She is:','["ignoring math", "skipping steps", "performing algebraic operations involving addition, subtraction, multiplication and division", "guessing"]'::jsonb,2,'Algebra.','original'),
('127.890.d.4.A',4,'In 3x + 6 = 21, the value of x is:','["7", "9", "3", "5"]'::jsonb,3,'x equals 5.','original'),
('127.890.d.4.B',3,'A mechanic needs the area of a rectangular panel 12 inches by 5 inches and the volume of a 4 by 3 by 2 inch block. She is:','["determining areas and volumes of various geometric shapes", "guessing", "skipping math", "ignoring shapes"]'::jsonb,0,'Area and volume.','original'),
('127.890.d.4.B',4,'The volume of a block 4 inches long, 3 inches wide and 2 inches high is:','["14 cubic inches", "24 cubic inches", "20 cubic inches", "9 cubic inches"]'::jsonb,1,'4x3x2.','original'),
('127.890.d.4.C',3,'A technician mixes a 3 to 1 ratio of cleaner to water and works out how much cleaner makes 12 quarts. She is:','["ignoring ratios", "guessing", "solving ratio, proportion and percentage problems", "skipping math"]'::jsonb,2,'Ratios.','original'),
('127.890.d.4.C',4,'A 3 to 1 ratio of cleaner to water, making 12 quarts total, uses how much cleaner?','["4 quarts", "3 quarts", "6 quarts", "9 quarts"]'::jsonb,3,'3/4 of 12.','original'),
('127.890.d.4.D',3,'A student finds the square root of 144 and raises 2 to the fifth power. She is:','["extracting roots and raising numbers to a given power", "guessing", "ignoring powers", "skipping math"]'::jsonb,0,'Roots and powers.','original'),
('127.890.d.4.D',4,'2 raised to the fifth power equals:','["16", "32", "10", "25"]'::jsonb,1,'2^5.','original'),
('127.890.d.5.A',3,'A mechanic finds the capacity of a rectangular tank 4 feet long, 3 feet wide and 2 feet deep. She is:','["ignoring volume", "guessing", "computing the volume of a shape such as a baggage compartment, a fuel tank or an aircraft", "skipping math"]'::jsonb,2,'Tank volume.','original'),
('127.890.d.5.A',4,'A compartment 5 feet long, 4 feet wide and 3 feet high has a volume of:','["12 cubic feet", "20 cubic feet", "47 cubic feet", "60 cubic feet"]'::jsonb,3,'5x4x3.','original'),
('127.890.d.5.B',3,'A mechanic multiplies the span by the chord to find the area of a rectangular wing. She is:','["computing the area of an aircraft wing", "skipping math", "guessing", "ignoring area"]'::jsonb,0,'Wing area.','original'),
('127.890.d.5.B',4,'A rectangular wing 30 feet long and 5 feet wide has an area of:','["60 square feet", "150 square feet", "100 square feet", "35 square feet"]'::jsonb,1,'30x5.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
